def transform(grid):
    g=[row[:] for row in grid]
    H,W=len(g),len(g[0])
    seed=next((r,c) for r in range(H) for c in range(W) if g[r][c]==3)
    lines=[]; seen=set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] in (1,2) and (r,c) not in seen:
                comp=[]; seen.add((r,c)); stack=[(r,c)]
                while stack:
                    x,y=stack.pop(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and grid[a][b] in (1,2) and (a,b) not in seen:
                            seen.add((a,b)); stack.append((a,b))
                rs=[x for x,y in comp]; cs=[y for x,y in comp]
                lines.append({'horizontal':min(rs)==max(rs),'r0':min(rs),'r1':max(rs),'c0':min(cs),'c1':max(cs),'n':sum(grid[x][y]==1 for x,y in comp)})
    for r in range(H):
        for c in range(W):
            if g[r][c]==1:g[r][c]=2
    r,c=seed; points=[(r,c)]
    # Approach and pass each obstacle. Each blue cell adds one cell of clearance.
    for i,line in enumerate(lines):
        m=line['n']+1
        if line['horizontal']:
            nr=line['r0']-m if r<line['r0'] else line['r1']+m
            points.append((nr,c)); r=nr
            nc=line['c0']-m if i%2==0 else line['c1']+m
            points.append((r,nc)); c=nc
            last='h'
        else:
            nc=line['c0']-m if c<line['c0'] else line['c1']+m
            points.append((r,nc)); c=nc
            nr=line['r1']+m if i%2==0 else line['r0']-m
            points.append((nr,c)); r=nr
            last='v'
    if last=='h':points.append((H-1,c))
    else:points.append((r,W-1))
    for (r,c),(nr,nc) in zip(points,points[1:]):
        dr=(nr>r)-(nr<r); dc=(nc>c)-(nc<c)
        while True:
            if 0<=r<H and 0<=c<W:g[r][c]=3
            if (r,c)==(nr,nc):break
            r+=dr;c+=dc
    return g

